import os, sys
from pathlib import Path
def load_table(the_path, to_format="csv"):
    the_file = Path(the_path)
    rows = []
    with the_file.open() as fh:
        for line in fh:
            parts = line.strip().split(",")
            if not parts:
                continue
            row = {"the_id": parts[0], "to": parts[1] if len(parts) > 1 else ""}
            rows.append(row)
    return rows
def save_table(the_rows, to_path, to_format="csv"):
    out = Path(to_path)
    with out.open("w") as fh:
        for r in the_rows:
            fh.write(f"{r['the_id']},{r['to']}\n")
def merge_tables(the_a, the_b, to_key="the_id"):
    index = {r[to_key]: r for r in the_b}
    out = []
    for r in the_a:
        key = r.get(to_key)
        if key in index:
            merged = dict(r)
            merged.update(index[key])
            out.append(merged)
    return out
def filter_ids(the_rows, to_keep):
    keep = set(to_keep)
    return [r for r in the_rows if r.get("the_id") in keep]
def rename_columns(the_rows, to_names):
    out = []
    for r in the_rows:
        out.append({to_names.get(k, k): v for k, v in r.items()})
    return out
if __name__ == "__main__":
    a = load_table(sys.argv[1], to_format="csv")
    b = load_table(sys.argv[2], to_format="csv")
    m = merge_tables(a, b, to_key="the_id")
